const products=[
 {name:"Laptop",price:60000,cat:"electronics",img:"image/laptop.jpg"},
 {name:"Mobile",price:20000,cat:"electronics",img:"image/mobile.jpg"},
 {name:"Book",price:500,cat:"books",img:"image/Books.jpg"}
];

const box=document.getElementById("productContainer");
const filter=document.getElementById("categoryFilter");

function display(data){
 box.innerHTML="";
 data.forEach(p=>{
  box.innerHTML+=`
   <div class="card">
    <img src="${p.img}" loading="lazy">
    <h3>${p.name}</h3>
    <p>₹${p.price}</p>
    <button onclick="addToCart('${p.name}')">Add to Cart</button>
   </div>`;
 });
}

filter.addEventListener("change",()=>{
 let v=filter.value;
 display(v==="all"?products:products.filter(p=>p.cat===v));
});

function addToCart(item){
 let cart=JSON.parse(localStorage.getItem("cart"))||[];
 cart.push(item);
 localStorage.setItem("cart",JSON.stringify(cart));
 alert("Added to cart");
}

display(products);
